import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <class TA, class TB, class TC>
__global__ static void
triu_gemm_device(int M, int N, int K,
                  TA const* A, int ldA,
                  TB const* B, int ldB,
                  TC      * C, int ldC)
{
  int bm = blockIdx.x;
  int bn = blockIdx.y;

  const int TILE = 128;
  constexpr int TILE_K = 16;
  int row_start = bm * TILE;
  int col_start = bn * TILE;
  int row_end   = row_start + TILE - 1;
  int col_end   = col_start + TILE - 1;

  // Entire tile lies strictly below the diagonal -> output is all zero
  // (C was pre-zeroed on the host side), so we can skip it entirely.
  if (row_start > col_end) return;

  // Determine the useful K range for this tile:
  //   A(row,k) == 0 for k < row  => smallest needed k is row_start
  //   B(k,col) == 0 for k > col  => largest needed k is col_end
  int k_lo = row_start;                    // multiple of TILE_K since TILE % TILE_K == 0
  int k_hi = col_start + TILE - 1 + 1;
  if (k_hi > K) k_hi = K;
  int k_hi_aligned = ((k_hi + TILE_K - 1) / TILE_K) * TILE_K;
  if (k_hi_aligned > K) k_hi_aligned = K;

  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(ldA, Int<1>{}));
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(N, K), make_stride(Int<1>{}, ldB));
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(ldC, Int<1>{}));

  auto cta_tiler = make_shape(Int<128>{}, Int<128>{}, Int<TILE_K>{});
  auto cta_coord = make_coord(bm, bn, _);
  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1,X,_1>{});
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X,_1,_1>{});
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1,X>{});

  constexpr int SMEM_LD = 128 + 4; // pad shared-mem leading dimension (stride not multiple of 32) to reduce bank conflicts
  __shared__ TA smemA[SMEM_LD*TILE_K*2];
  __shared__ TB smemB[SMEM_LD*TILE_K*2];
  Tensor sA0 = make_tensor(make_smem_ptr(smemA), make_shape(Int<128>{}, Int<TILE_K>{}), make_stride(Int<1>{}, Int<SMEM_LD>{}));
  Tensor sA1 = make_tensor(make_smem_ptr(smemA + SMEM_LD*TILE_K), make_shape(Int<128>{}, Int<TILE_K>{}), make_stride(Int<1>{}, Int<SMEM_LD>{}));
  Tensor sB0 = make_tensor(make_smem_ptr(smemB), make_shape(Int<128>{}, Int<TILE_K>{}), make_stride(Int<1>{}, Int<SMEM_LD>{}));
  Tensor sB1 = make_tensor(make_smem_ptr(smemB + SMEM_LD*TILE_K), make_shape(Int<128>{}, Int<TILE_K>{}), make_stride(Int<1>{}, Int<SMEM_LD>{}));
  auto tA = make_layout(make_shape(Int<16>{}, Int<16>{}), make_stride(Int<16>{}, Int<1>{}));
  auto tB = make_layout(make_shape(Int<16>{}, Int<16>{}));
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));
  Tensor tAgA = local_partition(gA, tA, threadIdx.x);
  Tensor tAsA0 = local_partition(sA0, tA, threadIdx.x);
  Tensor tAsA1 = local_partition(sA1, tA, threadIdx.x);
  Tensor tBgB = local_partition(gB, tB, threadIdx.x);
  Tensor tBsB0 = local_partition(sB0, tB, threadIdx.x);
  Tensor tBsB1 = local_partition(sB1, tB, threadIdx.x);
  Tensor tCsA0 = local_partition(sA0, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsA1 = local_partition(sA1, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsB0 = local_partition(sB0, tC, threadIdx.x, Step<X,_1>{});
  Tensor tCsB1 = local_partition(sB1, tC, threadIdx.x, Step<X,_1>{});
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1,_1>{});
  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);
  Tensor tArA = make_fragment_like(tAsA0);
  Tensor tBrB = make_fragment_like(tBsB0);
  int k_tile_start = k_lo / TILE_K;
  int k_tile_end   = k_hi_aligned / TILE_K; // exclusive
  int k_tile_count = k_tile_end - k_tile_start;
  if (k_tile_count > 0) {
    // Prologue: load first tile into buffer 0
    copy(tAgA(_,_,k_tile_start), tAsA0);
    copy(tBgB(_,_,k_tile_start), tBsB0);
    for (int k_tile = 0; k_tile < k_tile_count; ++k_tile) {
      __syncthreads();
      bool even = (k_tile % 2) == 0;
      // Prefetch next tile into registers (overlaps with the gemm below)
      if (k_tile + 1 < k_tile_count) {
        copy(tAgA(_,_,k_tile_start + k_tile + 1), tArA);
        copy(tBgB(_,_,k_tile_start + k_tile + 1), tBrB);
      }
      if (even) {
        gemm(tCsA0, tCsB0, tCrC);
      } else {
        gemm(tCsA1, tCsB1, tCrC);
      }
      // Stage the prefetched tile into the other shared-memory buffer
      if (k_tile + 1 < k_tile_count) {
        if (even) {
          copy(tArA, tAsA1);
          copy(tBrB, tBsB1);
        } else {
          copy(tArA, tAsA0);
          copy(tBrB, tBsB0);
        }
      }
      __syncthreads();
    }
  }

  // Fast path: if the entire tile lies strictly above the diagonal,
  // every element of this tile satisfies r <= c (since row_end < col_start),
  // so we can skip the per-element mask check entirely and issue a single
  // bulk (potentially vectorized) copy straight from registers to global memory.
  // This is true for the vast majority of valid (non-skipped) tiles, since only
  // the diagonal tiles (bm == bn) actually straddle the triangular boundary.
  if (row_end < col_start) {
    copy(tCrC, tCgC);
    return;
  }
  // Epilogue: write back only the upper-triangular part (r <= c),
  // using an identity-coordinate tensor tiled the same way as gC.
  Tensor identity = make_identity_tensor(make_shape(M, N));
  Tensor cC  = local_tile(identity, cta_tiler, cta_coord, Step<_1,_1,X>{});
  Tensor tCcC = local_partition(cC, tC, threadIdx.x, Step<_1,_1>{});
  CUTE_UNROLL
  for (int i = 0; i < size(tCrC); ++i) {
    int r = get<0>(tCcC(i));
    int c = get<1>(tCcC(i));
    if (r <= c) {
      tCgC(i) = tCrC(i);
    }
  }
}

torch::Tensor triu_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim()==2 && B.dim()==2,  "A and B must be 2D");
  TORCH_CHECK(A.scalar_type()==at::kFloat && B.scalar_type()==at::kFloat,
              "Expect float32 tensors");

  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int N = (int)B.size(1);
  TORCH_CHECK((int)B.size(0) == K, "Inner dimensions must match");
  TORCH_CHECK(M % 128 == 0 && N % 128 == 0 && K % 16 == 0,
              "This kernel requires M,N multiple of 128 and K multiple of 16");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::zeros({M, N}, A.options());

  int ldA = K; // row-major (M,K)
  int ldB = N; // row-major (K,N)
  int ldC = N; // row-major (M,N)

  dim3 dimBlock(256);
  dim3 dimGrid(M / 128, N / 128);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  triu_gemm_device<float,float,float><<<dimGrid, dimBlock, 0, stream>>>(
      M, N, K,
      A_c.data_ptr<float>(), ldA,
      B_c.data_ptr<float>(), ldB,
      C.data_ptr<float>(), ldC);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "triu_gemm launch failed: ", cudaGetErrorString(err));

  return C;
}
"""

cutlass_triu = load_inline(
    name="cutlass_triu_matmul_inline",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["triu_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute",
    ],
    verbose=False,
)


